written = []
for cid, d in P.items():
    obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    p = OUT / f"{cid}.json"
    p.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    written.append(cid)

# self-verify: reopen each exact file only
ok = 0
for cid in written:
    obj = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
    assert obj["case_id"] == cid
    assert set(obj.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
    t = obj["trigger"]
    assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    assert isinstance(t["reason"], str) and t["reason"]
    assert 0 <= obj["confidence"] <= 1
    assert obj["basis"].splitlines()[0] == "liuyao"
    ok += 1
cm = sum(1 for c in written if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in written if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in written if P[c]["trigger"]["disputed"])
print(f"written={ok} changed_main={cm} reserve_used={ru} disputed={di}")
